corrected_code:
package forum

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"myapp/moderation"
)

func ConfigureModerationRoutes(r *gin.Engine, modSvc moderation.Service) {
	modGroup := r.Group("/moderation")
	modGroup.Use(moderation.ModeratorSessionRequired())

	modGroup.POST("/comments/:commentID/hide", func(c *gin.Context) {
		commentID := c.Param("commentID")
		forumID := c.GetString("moderator_forum_id")

		err := modSvc.HideCommentInForum(c.Request.Context(), commentID, forumID)
		if err != nil {
			c.JSON(http.StatusForbidden, gin.H{"error": "Unauthorized or comment not in forum"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"hidden": true})
	})
}
